const PizZip = require('pizzip');
const fs = require('fs');
const path = '/workspace/testbed/docs/travel_summary.docx';
const content = fs.readFileSync(path);
const zip = new PizZip(content);
let xml = zip.file('word/document.xml').asText();

// Update booking BK-B70889: add route JFK → LHR (status is already confirmed)
const oldText = 'Booking BK-B70889 | user_59b22691 |  →  | business | Status: confirmed | \$1180';
const newText = 'Booking BK-B70889 | user_59b22691 | JFK → LHR | business | Status: confirmed | \$1180';

if (xml.includes(oldText)) {
  xml = xml.replace(oldText, newText);
  zip.file('word/document.xml', xml);
  const out = zip.generate({ type: 'nodebuffer' });
  fs.writeFileSync(path, out);
  console.log('SUCCESS: Updated BK-B70889 route to JFK → LHR');
} else {
  console.log('ERROR: Could not find the booking text to replace');
  console.log('Searching for BK-B70889...');
  const idx = xml.indexOf('BK-B70889');
  if (idx >= 0) console.log('Found at index', idx, ':', xml.substring(idx-20, idx+100));
}
"

